function validate([binary]) {
  if (typeof binary !== 'string' || binary.length < 1 || binary.length > 100000) return 'binary needs 1 to 10^5 characters.';
  if (!/^[01]+$/.test(binary)) return "binary may only contain '0' and '1'.";
  return null;
}

