function maximumBinaryString(binary) {
  const firstZero = binary.indexOf('0');
  if (firstZero === -1) {
    return binary;
  }
  let zeros = 0;
  for (let i = firstZero; i < binary.length; i++) {
    if (binary[i] === '0') {
      zeros++;
    }
  }
  const zeroAt = firstZero + zeros - 1;
  const ones = '1'.repeat(binary.length);
  return ones.slice(0, zeroAt) + '0' + ones.slice(zeroAt + 1);
}

