function maximumBinaryString(binary) {
  const visited = new Set([binary]);
  const queue = [binary];
  let best = binary;
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head];
    if (current > best) best = current;
    for (let i = 0; i + 1 < current.length; i++) {
      const pair = current.slice(i, i + 2);
      let next = null;
      if (pair === '00') next = current.slice(0, i) + '10' + current.slice(i + 2);
      if (pair === '10') next = current.slice(0, i) + '01' + current.slice(i + 2);
      if (next !== null && !visited.has(next)) {
        visited.add(next);
        queue.push(next);
      }
    }
  }
  return best;
}

