function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 9);
  const zeroChance = [0, 0.1, 0.5, 0.9, 1][Math.floor(rand() * 5)];
  let binary = '';
  for (let i = 0; i < n; i++) binary += rand() < zeroChance ? '0' : '1';
  return [binary];
}
